const GROUPS = ['None', 'Keyboard', 'Mouse', 'Media', 'Text', 'Layers', 'LED Control', 'Macros'] as const;
type MouseButtonAction = Extract<Action, { type: 'mouseClick' | 'mouseHold' | 'mouseToggle' | 'mouseDown' | 'mouseUp' }>;
const MOUSE_BEHAVIORS = [
  { type: 'mouseClick', label: 'Click', hint: 'Press and release the selected buttons.' },
  { type: 'mouseHold', label: 'Hold', hint: 'Hold the selected buttons until you release the physical button.' },
  { type: 'mouseToggle', label: 'Toggle', hint: 'Press once to hold; press again to release.' },
  { type: 'mouseDown', label: 'Down', hint: 'Press the selected buttons and leave them down.' },
  { type: 'mouseUp', label: 'Up', hint: 'Release buttons held by Down or Toggle.' },
] as const;
function isMouseButtonAction(action: Action): action is MouseButtonAction {
  return MOUSE_BEHAVIORS.some(behavior => behavior.type === action.type);
}
type PointerAction = Extract<Action, { type: 'mouseX' | 'mouseY' | 'mouseXY' }>;
function isPointerAction(action: Action): action is PointerAction {
  return action.type === 'mouseX' || action.type === 'mouseY' || action.type === 'mouseXY';
}

function ConsumerUsageInput({ usage, onChange, reduced = false }: { usage: number; onChange(usage: number): void; reduced?: boolean }) {
  const [draft, setDraft] = useState<string | null>(null);
  const digits = reduced ? 2 : 3;
  const value = draft ?? usage.toString(16).toUpperCase().padStart(digits, '0');
  const valid = /^[0-9a-f]{1,3}$/i.test(value) && parseInt(value, 16) > 0 && parseInt(value, 16) <= (reduced ? 0xff : 0xfff);
  const commit = () => {
    if (valid) onChange(parseInt(value, 16));
    setDraft(null);
  };
  return <input class="mono" value={value} maxLength={digits} aria-label="Consumer Usage in Hex"
    aria-invalid={!valid} title={reduced ? "Enter a hexadecimal usage from 01 to FF" : "Enter a hexadecimal usage from 001 to FFF"}
    onInput={(e) => {
      const input = e.currentTarget;
      const cursor = input.selectionStart;
      const beforeCursor = cursor === null ? null : input.value.slice(0, cursor).replace(/[^0-9a-f]/gi, '').length;
      const filtered = input.value.replace(/[^0-9a-f]/gi, '');
      if (input.value !== filtered) {
        input.value = filtered;
        if (beforeCursor !== null) input.setSelectionRange(beforeCursor, beforeCursor);
      }
      setDraft(filtered);
    }}
    onBlur={commit}
    onKeyDown={(e) => {
      if (e.key === 'Enter') e.currentTarget.blur();
      if (e.key === 'Escape') setDraft(null);
    }} />;
}

function ConsumerControl({ action, onChange }: {
  action: Extract<Action, { type: 'consumer' | 'consumerHold' | 'consumerModified' | 'consumerModifiedHold' }>;
  onChange(action: Action): void;
}) {
  const reduced = action.type === 'consumerModified' || action.type === 'consumerModifiedHold';
  const choices = CONSUMER_USAGES.filter(c => !reduced || c.usage <= 0xff);
  const [customSelected, setCustomSelected] = useState(false);
  const custom = customSelected || !choices.some((c) => c.usage === action.usage);
  return (
        <div class="field">
          <span class="field-label">Control</span>
          <select value={custom ? 'custom' : action.usage} onChange={(e) => {
            const v = (e.target as HTMLSelectElement).value;
            setCustomSelected(v === 'custom');
            if (v !== 'custom') onChange({ ...action, usage: Number(v) });
          }}>
            {CONSUMER_GROUPS.map((group) => (
              <optgroup key={group} label={group}>
                {choices.filter((c) => c.group === group).map((c) => <option key={c.usage} value={c.usage}>{c.name}</option>)}
              </optgroup>
            ))}
            <optgroup label="Advanced"><option value="custom">Custom Usage…</option></optgroup>
          </select>
          {custom && (
            <div class="row">
              <span class="mono">0x</span>
              <ConsumerUsageInput key={action.usage} usage={action.usage} reduced={reduced}
                onChange={(usage) => onChange({ ...action, usage })} />
              <span class="hint">{reduced ? "8-bit" : "12-bit"} HID Consumer Page usage</span>
            </div>
          )}
          <span class="hint">Brightness controls are honored by some hosts and monitors only.</span>
          {(action.type === 'consumerHold' || action.type === 'consumerModifiedHold') && <span class="hint">The host decides whether a held control repeats. The newest media action wins; previous holds are not restored. Holds continue across layer changes until release.</span>}
        </div>
  );
}

function MouseButtons({ value, onChange }: { value: number; onChange(v: number): void }) {
  const buttons = MOUSE_BUTTONS;
  const [showMore, setShowMore] = useState(!!(value & 0xE0));
  useEffect(() => {
    if (value & 0xE0) setShowMore(true);
  }, [value]);
  const buttonControl = (b: typeof buttons[number]) => (
    <label key={b.bit} class={`chip ${value & b.bit ? 'chip-on' : ''}`}>
      <input type="checkbox" checked={!!(value & b.bit)} onChange={(e) => onChange((e.target as HTMLInputElement).checked ? value | b.bit : value & ~b.bit)} />
      {b.label}
    </label>
  );
  return (
    <div class="field">
      <span class="field-label">Mouse Buttons</span>
      <div class="chips mouse-button-picker">
        {buttons.slice(0, 5).map(buttonControl)}
        <button type="button" class="inline-link" aria-expanded={showMore} onClick={() => setShowMore(!showMore)}>{showMore ? 'Less' : 'More'}</button>
        {showMore && buttons.slice(5).map(buttonControl)}
      </div>
    </div>
  );
}

function DirectionalStep({ label, directionLabel, negativeLabel, positiveLabel, hint, value, onChange, onTest, children, directionFirst = false, min = 1, max = 127, step = 1 }: {
  label: string;
  directionLabel: string;
  negativeLabel: string;
  positiveLabel: string;
  hint?: string;
  value: number;
  onChange(v: number): void;
  onTest?(): void;
  children?: ComponentChildren;
  directionFirst?: boolean;
  min?: number;
  max?: number;
  step?: number;
}) {
  const [zeroNegative, setZeroNegative] = useState(false);
  const magnitude = Math.max(min, Math.min(max, Math.abs(value)));
  const negative = value < 0 || (value === 0 && zeroNegative);
  const setMagnitude = (next: number) => {
    const amount = Math.max(min, Math.min(max, Math.round(next / step) * step));
    if (!amount) setZeroNegative(negative);
    onChange(amount ? (negative ? -amount : amount) : 0);
  };
  const setDirection = (nextNegative: boolean) => {
    setZeroNegative(nextNegative);
    if (magnitude) onChange((nextNegative ? -1 : 1) * magnitude);
  };
  const direction = (
      <div class="field scroll-direction">
        <span class="field-label">{directionLabel}</span>
        <div class="segmented" role="group" aria-label={directionLabel}>
          <button type="button" class={negative ? 'is-selected' : ''} aria-pressed={negative} onClick={() => setDirection(true)}>{negativeLabel}</button>
          <button type="button" class={!negative ? 'is-selected' : ''} aria-pressed={!negative} onClick={() => setDirection(false)}>{positiveLabel}</button>
        </div>
        {onTest && <span class="hint">Some computers may invert these settings, in which case you will need to swap {negativeLabel.toLowerCase()} and {positiveLabel.toLowerCase()}. <button type="button" class="inline-link" onClick={onTest}>Click Here</button> to test the scrolling behavior.</span>}
      </div>
  );
  return (
    <div class={`field${directionFirst ? ' direction-first' : ''}`}>
      {directionFirst && direction}
      <span class="field-label">{label} <output>{magnitude}</output></span>
      <input type="range" min={min} max={max} step={step} value={magnitude} aria-label={label} onInput={(e) => setMagnitude(Number((e.target as HTMLInputElement).value))} />
      {hint && <span class="hint">{hint}</span>}
      {children}
      {!directionFirst && direction}
    </div>
  );
}

export function Inspector() {
  const [showScrollTest, setShowScrollTest] = useState(false);
  const p = profile.value;
  const slot = selectedSlot.value;
  const action = p && slot ? getAction(p, slot) : undefined;
  const timed = slot?.kind === 'timed';
  const macro = slot?.kind === 'macro';
  const rotation = slot?.kind === 'macro' || slot?.kind === 'timed' || slot?.kind === 'clockwise' || slot?.kind === 'counterclockwise';
  const layerCount = p?.layers.length ?? 0;
  const actionContext = { layerCount, rotation: !!rotation, timed, macro, macros: p?.macros, macroCount: p?.macros?.length ?? 0 };
  const problem = action ? actionProblem(action, actionContext) : null;
  const actionDescriptor = action && ACTION_DESCRIPTORS.find((candidate) => candidate.type === action.type);
  const savedStrings = useMemo(() => {
    if (!p) return [];
    const strings = new Set<string>();
    const add = (candidate: Action) => {
      if (candidate.type === 'string' && candidate.text.length > 0) strings.add(candidate.text);
    };
    for (const savedLayer of p.layers) {
      savedLayer.keys.forEach(add);
      add(savedLayer.encoderButton);
      add(savedLayer.clockwise);
      add(savedLayer.counterclockwise);
    }
    p.chords.forEach((chord) => add(chord.action));
    p.timedActions?.forEach((timer) => { add(timer.action); add(timer.resumeAction); });
    p.macros?.forEach(macro => macro.actions.forEach(add));
    return [...strings];
  }, [p]);

  if (!p || !slot || !action) {
    return (
      <section class="card inspector inspector-empty">
        <h2>Action Editor</h2>
        <p class="muted">Select a key, the encoder, a chord, a timed action, or a macro step on the left to edit what it does.</p>
      </section>
    );
  }

  const update = (next: Action) => setAction(slot, next);
  const ledRelativeSteps = action.type === 'ledControl' &&
    (action.command === 'rainbowPhaseRelative' || action.command === 'rainbowSpeedRelative')
    ? [-2, -1, 1, 2] : [-1, 1];
  const setType = (type: ActionType) => {
    if (actionFamilyType(type) !== type || (rotation && ACTION_DESCRIPTORS.find(d => d.type === type)?.needsRelease)) return;
    if (type === 'mouseX' && isPointerAction(action)) return;
    if (type === 'mouseClick' && isMouseButtonAction(action)) return;
    if (type === actionFamilyType(action.type)) return;
    setAction(slot, action);
    const saved = rememberedFamilyAction(slot, type);
    const remembered = saved && !actionProblem(saved, actionContext) ? saved : undefined;
    if ((type === 'consumer' || type === 'consumerModified') && isMediaAction(action)) {
      const targetType = ACTION_FAMILIES[type][actionNeedsRelease(action) && !rotation ? 1 : 0];
      const previous = rememberedAction(slot, targetType);
      const next = previous && !actionProblem(previous, actionContext) ? previous : blankAction(targetType);
      if (isMediaAction(next)) {
        const usage = type === 'consumerModified' && action.usage > 0xff ? next.usage : action.usage;
        update('modifiers' in next ? { ...next, usage, modifiers: 'modifiers' in action ? action.modifiers : next.modifiers } : { ...next, usage });
      }
      return;
    }
    if ((type === 'setLayer' || type === 'relativeLayer') && isLayerAction(action)) {
      const sourceTypes = ACTION_FAMILIES[actionFamilyType(action.type) as 'setLayer' | 'relativeLayer'];
      const mode = (sourceTypes as readonly ActionType[]).indexOf(action.type);
      const targetType = ACTION_FAMILIES[type][mode === 2 && rotation ? 0 : mode]!;
      const previous = rememberedAction(slot, targetType);
      update(previous && !actionProblem(previous, actionContext) ? previous : blankAction(targetType));
      return;
    }
    if (remembered) { update(remembered); return; }
    const next = blankAction(type);
    // Carry compatible values between related actions.
    if ('buttons' in next && 'buttons' in action) update({ ...next, buttons: action.buttons });
    else if ('layer' in next && 'layer' in action) update({ ...next, layer: action.layer });
    else if ('delta' in next && 'delta' in action) update({ ...next, delta: action.delta,
      ...('hold' in action && action.hold && !rotation ? { hold: true } : {}) });
    else if ('offset' in next && 'offset' in action) update({ ...next, offset: action.offset });
    else update(next);
  };

  const setFamilyBehavior = (type: ActionType) => {
    if ((!isKeyAction(action) && !isMediaAction(action) && !isLayerAction(action)) || actionFamilyType(type) !== actionFamilyType(action.type) || type === action.type) return;
    const next = { ...action, type } as Action;
    if (actionProblem(next, actionContext)) return;
    update(next);
  };

  const setMouseBehavior = (type: MouseButtonAction['type']) => {
    if (!isMouseButtonAction(action) || action.type === type || (type === 'mouseHold' && rotation)) return;
    setAction(slot, action);
    const remembered = rememberedAction(slot, type);
    const next = remembered && isMouseButtonAction(remembered) ? remembered : blankAction(type);
    if (isMouseButtonAction(next)) update({ ...next, buttons: action.buttons });
  };

  const setMovementAxis = (type: PointerAction['type']) => {
    if (!isPointerAction(action) || action.type === type) return;
    setAction(slot, action);
    const remembered = rememberedAction(slot, type);
    const hold = !rotation && action.hold ? { hold: true } : {};
    if (remembered && isPointerAction(remembered)) {
      update({ ...remembered, hold: hold.hold });
    } else if (type === 'mouseXY') {
      const delta = action.type === 'mouseXY' ? action.x : action.delta;
      const amount = (delta < 0 ? -1 : 1) * Math.max(4, Math.min(64, Math.round(Math.abs(delta) / 4) * 4));
      update({ type, x: action.type === 'mouseY' ? 4 : amount, y: action.type === 'mouseY' ? amount : 4, ...hold });
    } else {
      const delta = action.type === 'mouseXY' ? (type === 'mouseX' ? action.x : action.y) || 4 : action.delta;
      update({ type, delta, ...hold });
    }
  };
  const selectableActions = ACTION_DESCRIPTORS.filter(d => actionFamilyType(d.type) === d.type && d.type !== 'mouseY' && d.type !== 'mouseXY' &&
    !MOUSE_BEHAVIORS.some(behavior => behavior.type === d.type && behavior.type !== 'mouseClick')).filter(d => macro
    ? d.type !== 'macro' && d.type !== 'none' && !d.needsRelease
    : d.type !== 'pause');
  const singleRun = action.type === 'macro' && macroSwitchesLayer(p.macros?.[action.macro]?.actions ?? []);
  const keyIndex = slot.kind === 'key' ? slot.index : null;
  const layer = p.layers[slot.layer]!;

  return (
    <section class="card inspector">
      <header class="card-head">
        <div class="inspector-title">
          <h2>{slot.kind === 'timed' || slot.kind === 'macro' ? slotLabel(slot) : slotLabel(slot).split(' · ')[1]}</h2>
          <span class="muted">{slot.kind === 'timed' || slot.kind === 'macro' ? 'Across All Layers' : layerName(slot.layer)}</span>
        </div>
        {slot.kind === 'chord' && (
          <button class="btn btn-icon btn-ghost" aria-label="Remove Chord" onClick={() => removeChord(slot)}><IconTrash /></button>
        )}
      </header>

      <label class="field">
        <span class="field-label">Action</span>
        <select value={isPointerAction(action) ? 'mouseX' : isMouseButtonAction(action) ? 'mouseClick' : actionFamilyType(action.type)} onChange={(e) => setType((e.target as HTMLSelectElement).value as ActionType)}>
          {!actionDescriptor && <option value={action.type} disabled>Unsupported Saved Action</option>}
          {GROUPS.filter(group => selectableActions.some(d => d.group === group)).map((group) => (
            <optgroup key={group} label={group}>
              {selectableActions.filter(d => d.group === group).map((d) => (
                <option key={d.type} value={d.type} disabled={rotation && d.needsRelease}>
                  {d.type === 'keyTap' ? 'Key Press' : d.type === 'mouseX' ? 'Move Mouse' : d.label}{rotation && d.needsRelease ? ' (Buttons Only)' : ''}
                </option>
              ))}
            </optgroup>
          ))}
        </select>
        {!isKeyAction(action) && actionFamilyType(action.type) !== 'relativeLayer' && <span class="hint">{isPointerAction(action) ? 'Move the pointer horizontally, vertically, or on both axes.' : isMouseButtonAction(action) ? 'Click, hold, toggle, press, or release mouse buttons.' : actionDescriptor?.hint ?? 'This saved action is no longer supported. Choose another action.'}</span>}
      </label>

      {(isKeyAction(action) || isMediaAction(action) || isLayerAction(action)) && <div class="field">
        <span class="field-label">Behavior</span>
        <div class="segmented" role="group" aria-label={isKeyAction(action) ? 'Key Behavior' : isMediaAction(action) ? 'Media Behavior' : 'Layer Behavior'} aria-describedby="family-behavior-hint">
          {ACTION_FAMILIES[actionFamilyType(action.type) as keyof typeof ACTION_FAMILIES].map((type, index) => {
            const label = isLayerAction(action) ? ['Switch', 'One-Shot', 'Hold'][index] : ['Tap', 'Hold'][index];
            const hold = ACTION_DESCRIPTORS.find(d => d.type === type)!.needsRelease;
            return <button key={type} type="button" class={action.type === type ? 'is-selected' : ''} aria-pressed={action.type === type}
              disabled={hold && (rotation || isPreviousLayer(action))} onClick={() => setFamilyBehavior(type)}>{label}</button>;
          })}
        </div>
        <span class="hint" id="family-behavior-hint">
          {isMediaAction(action)
            ? actionNeedsRelease(action) ? 'Hold the selected control until physical release.' : 'Press and release the selected control once.'
            : actionDescriptor?.hint}
          {rotation && <> Hold is not available on this input because it has no physical release.</>}
          {isPreviousLayer(action) && !rotation && <> Hold is not available for Previous Layer. Choose a specific target layer to use Hold.</>}
        </span>
      </div>}

      {macro && isMacroLayerSwitch(action) && <p class="hint">A layer switch must be the final macro step. Macros containing a layer switch must run once, even if the target layer is already active.</p>}
      {action.type === 'macro' && <>
        <label class="field"><span class="field-label">Macro</span>
          <select aria-label="Macro" value={action.macro} onChange={e => { const index = Number((e.target as HTMLSelectElement).value); update({ ...action, macro: index, repeats: macroSwitchesLayer(p.macros?.[index]?.actions ?? []) ? 1 : action.repeats }); }}>
            {!p.macros?.[action.macro] && <option value={action.macro}>Choose a Macro — Add One in Macros</option>}
            {p.macros?.map((macro, index) => <option value={index}>Macro {index + 1} ({macro.actions.length} step{macro.actions.length === 1 ? '' : 's'})</option>)}
          </select>
        </label>
        {(!singleRun || action.repeats > 1) && <div class="field">
          <span class="field-label">Repeat</span>
          <div class="segmented" role="group" aria-label="Repeat">
            <button type="button" class={action.repeats > 1 ? 'is-selected' : ''} aria-pressed={action.repeats > 1} disabled={singleRun} onClick={() => update({ ...action, repeats: singleRun ? 1 : Math.max(2, action.repeats) })}>On</button>
            <button type="button" class={action.repeats === 1 ? 'is-selected' : ''} aria-pressed={action.repeats === 1} onClick={() => update({ ...action, repeats: 1 })}>Off</button>
          </div>
          {action.repeats > 1 && <label class="field macro-run-count-field">
            <span class="field-label">Run Count <output>{action.repeats}</output></span>
            <input type="range" aria-label="Run Count" min={2} max={16} step={1} disabled={singleRun} value={action.repeats} onInput={e => update({ ...action, repeats: singleRun ? 1 : Math.max(2, Math.min(16, Math.round(Number((e.target as HTMLInputElement).value) || 2))) })} />
          </label>}
        </div>}
      </>}
      {singleRun && <p class="hint">This macro switches layers, so it cannot be repeated</p>}
      {action.type === 'pause' && <label class="field"><span class="field-label">Pause Duration <output>{action.ticks * 16}ms</output></span>
        <input type="range" aria-label="Pause Duration" min={0} max={255} value={action.ticks} onInput={e => update({ ...action, ticks: Number((e.target as HTMLInputElement).value) })} />
        <span class="hint">16ms steps. Add consecutive pauses for longer waits.</span>
      </label>}
      {action.type === 'ledControl' && <>
        <label class="field"><span class="field-label">LED Command</span>
          <select value={isLedEffect(action.command) ? 'temporaryEffect' : action.command} onChange={(e) => {
            const selection = (e.target as HTMLSelectElement).value;
            const command = (selection === 'temporaryEffect' ? 'effectRestore' : selection) as LedCommand;
            const spec = ledCommandSpec(command);
            if (!spec) return;
            update({ type: 'ledControl', command, value: spec.relative ? 1 : command === 'restoreAll' || command === 'effectRestore' ? 0 : command === 'commonPresetSet' ? 0 : command === 'commonPresetToggle' ? 3 : 'asConfigured' });
          }}>
            {LED_COMMANDS.filter((c) => c.command !== 'restoreAll' && !isLedEffect(c.command)).map((c) => <option value={c.command}>{c.label}</option>)}
            <option value="temporaryEffect">Set All LEDs</option>
            <option value="" disabled>────────────────────</option>
            {LED_COMMANDS.filter((c) => c.command === 'restoreAll').map((c) => <option value={c.command}>{c.label}</option>)}
          </select>
        </label>
        {isLedEffect(action.command) ? <>
          <label class="field"><span class="field-label">Effect</span>
            <select value={action.command.startsWith('effectBlink') ? 'blink' : action.command} onChange={(e) => {
              const selection = (e.target as HTMLSelectElement).value;
              if (!['effectRestore', 'effectOn', 'blink'].includes(selection)) return;
              const command = (selection === 'blink' ? 'effectBlink1' : selection) as LedCommand;
              update({ type: 'ledControl', command, value: command === 'effectRestore' ? 0 : action.command === 'effectRestore' ? 15 : action.value,
                ...(command !== 'effectRestore' && action.brightness === 'dim' ? { brightness: 'dim' as const } : {}) });
            }}>
              <option value="effectRestore">As Configured</option>
              <option value="effectOn">Always On</option>
              <option value="blink">Blink</option>
            </select>
          </label>
          {action.command.startsWith('effectBlink') && <label class="field">
            <span class="field-label">Blink Count <output>{ledCommandSpec(action.command)!.code - 0x81} {action.command === 'effectBlink1' ? 'time' : 'times'}</output></span>
            <input type="range" min={1} max={8} step={1} value={ledCommandSpec(action.command)!.code - 0x81} aria-label="Blink Count" onInput={(e) => {
              const count = Number((e.target as HTMLInputElement).value);
              if (Number.isInteger(count) && count >= 1 && count <= 8) update({ ...action, command: `effectBlink${count}` as LedCommand });
            }} />
          </label>}
          {action.command !== 'effectRestore' && <div class="field led-color-field">
            <span class="field-label">Color</span>
            <div class="palette" role="radiogroup" aria-label="Temporary LED Effect Color">
              {PALETTE.map(c => <button type="button" role="radio" aria-checked={action.value === c.index}
                aria-label={c.index === 15 ? 'Rainbow' : c.name} title={c.index === 15 ? 'Rainbow' : c.name}
                class={`swatch-btn ${action.value === c.index ? 'is-selected' : ''}`}
                style={c.index === 15 ? 'background:linear-gradient(135deg, red, yellow, lime, cyan, blue, magenta)' : `--c:${c.hex}`}
                onClick={() => update({ ...action, value: c.index })} />)}
            </div>
            <div class="segmented" role="group" aria-label="Temporary LED Effect Brightness">
              <button type="button" class={action.brightness !== 'dim' ? 'is-selected' : ''}
                aria-pressed={action.brightness !== 'dim'} onClick={() => {
                  const { brightness, ...brightAction } = action;
                  update(brightAction);
                }}>Full Brightness</button>
              <button type="button" class={action.brightness === 'dim' ? 'is-selected' : ''}
                aria-pressed={action.brightness === 'dim'} onClick={() => update({ ...action, brightness: 'dim' })}>Dim</button>
            </div>
          </div>}
          <p class="hint">Always On persists until replaced, restored, or the layer changes. Key feedback can cover it. Blinking covers key feedback. Clearing or finishing an effect restores normal lighting without replaying the layer's blink or timed indication; brightness overrides remain in effect.</p>
        </> : ledCommandSpec(action.command)?.relative ?
          <label class="field"><span class="field-label">Relative Step</span>
            <select value={action.value} onChange={(e) => {
              const value = Number((e.target as HTMLSelectElement).value);
              if (ledRelativeSteps.includes(value)) update({ ...action, value });
            }}>
              {(typeof action.value !== 'number' || !ledRelativeSteps.includes(action.value)) &&
                <option value={action.value} disabled>Current: {typeof action.value === 'number' && action.value > 0 ? '+' : ''}{action.value}</option>}
              {ledRelativeSteps.map((v) => <option value={v}>{v > 0 ? '+' : ''}{v}</option>)}
            </select>
            <span class="hint">{ledRelativeCycle(action.command, action.value)}</span>
          </label>
          : action.command !== 'restoreAll' && <label class="field"><span class="field-label">{action.command === 'commonPresetToggle' ? 'Preset' : 'LED Setting'}</span>
            <select value={action.value} onChange={(e) => { const v = (e.target as HTMLSelectElement).value; update({ ...action, value: v === 'asConfigured' ? v : Number(v) as LedValue }); }}>
              {ledValueOptions(action.command).map((o) => <option value={o.value}>{o.label}</option>)}
            </select>
            {action.command === 'commonPresetToggle' && <span class="hint">Press to apply this preset. When it is active, press again to restore configured layer and key brightness. Rainbow speed and phase stay unchanged.</span>}
          </label>}
        {!isLedEffect(action.command) && <p class="hint">{action.command === 'commonPresetToggle'
          ? 'Lighting overrides apply across layers. Indicator brightness preserves its configured visibility mode.'
          : 'Lighting overrides apply across layers. Key LEDs off lets the idle background show. Both-relative starts from the brighter current brightness, applies the step once, and sets both to the result. As Configured resolves to the current layer indicator brightness and bright key feedback. Common presets include configured behavior. Indicator brightness preserves its configured visibility mode.'}</p>}
      </>}

      {(action.type === 'consumerModified' || action.type === 'consumerModifiedHold') && (
        <ModifierPicker modifiers={action.modifiers} onChange={(modifiers) => update({ ...action, modifiers })} />
      )}

      {(action.type === 'keyTap' || action.type === 'keyHold') && (
        <KeyPicker usage={action.usage} modifiers={action.modifiers} onChange={(usage, modifiers) => update({ ...action, usage, modifiers })} />
      )}

      {isMouseButtonAction(action) && <>
        <label class="field">
          <span class="field-label">Behavior</span>
          <select aria-label="Mouse Behavior" aria-describedby="mouse-behavior-hint" value={action.type}
            onChange={e => setMouseBehavior((e.target as HTMLSelectElement).value as MouseButtonAction['type'])}>
            {MOUSE_BEHAVIORS.map(behavior => <option key={behavior.type} value={behavior.type} disabled={behavior.type === 'mouseHold' && rotation}>{behavior.label}</option>)}
          </select>
          <span class="hint" id="mouse-behavior-hint">
            {MOUSE_BEHAVIORS.find(behavior => behavior.type === action.type)?.hint}
            {rotation && <> Hold is not available on this input.</>}
          </span>
        </label>
        <MouseButtons value={action.buttons} onChange={(buttons) => update({ ...action, buttons })} />
      </>}

      {(action.type === 'mouseDown' || action.type === 'mouseUp' || action.type === 'mouseToggle') && <p class="hint">Persistent mouse state is shared across inputs and macros. Layer changes and resets clear it; macro completion does not.</p>}
      {'buttons' in action && (action.buttons & 0xF8) !== 0 && <p class="hint">Buttons 4–8 depend on your operating system and application. Browser Back/Forward mappings are common for buttons 4/5, but are not guaranteed.</p>}

      {action.type === 'mouseClick' && (
        <div class="field">
          <span class="field-label">Clicks</span>
          <div class="segmented" role="group" aria-label="Click Behavior">
            <button type="button" class={(action.clicks ?? 1) === 1 ? 'is-selected' : ''} aria-pressed={(action.clicks ?? 1) === 1} onClick={() => update({ type: 'mouseClick', buttons: action.buttons })}>Single</button>
            <button type="button" class={action.clicks === 2 ? 'is-selected' : ''} aria-pressed={action.clicks === 2} onClick={() => update({ ...action, clicks: 2 })}>Double</button>
            <button type="button" class={(action.clicks ?? 1) >= 3 ? 'is-selected' : ''} aria-pressed={(action.clicks ?? 1) >= 3} onClick={() => update({ ...action, clicks: (action.clicks ?? 1) >= 3 ? action.clicks : rememberedCustomClickCount(slot) })}>Custom</button>
          </div>
          {(action.clicks ?? 1) >= 3 && <label class="field click-count-field">
            <span class="field-label">Click Count <output>{action.clicks}</output></span>
            <input type="range" min={3} max={16} step={1} value={action.clicks} aria-label="Click Count" onInput={(e) => update({ ...action, clicks: Math.max(3, Math.min(singleRun ? 1 : 16, Math.round(Number((e.target as HTMLInputElement).value)))) })} />
            <span class="hint">This click action will take about {(((action.clicks ?? 1) * 8 + ((action.clicks ?? 1) - 1) * 200) / 1000).toFixed(1)} seconds, delaying subsequent queued actions.</span>
          </label>}
        </div>
      )}

      {isMouseButtonAction(action) && (
        <p class="hint"><button type="button" class="inline-link" onClick={() => setShowScrollTest(true)}>Click Here</button> to test your configured mouse events.</p>
      )}

      {action.type === 'scroll' && (
        <DirectionalStep onTest={() => setShowScrollTest(true)} label="Wheel Step" directionLabel="Scroll Direction" negativeLabel={action.horizontal ? 'Left' : 'Up'} positiveLabel={action.horizontal ? 'Right' : 'Down'} hint={action.hold ? 'Wheel counts per repeat.' : 'Wheel counts per press or encoder detent.'} value={action.delta} onChange={(delta) => update({ ...action, delta })}>
          <div class="field">
            <span class="field-label">Scroll Axis</span>
            <div class="segmented" role="group" aria-label="Scroll Axis">
              <button type="button" class={!action.horizontal ? 'is-selected' : ''} aria-pressed={!action.horizontal} onClick={() => update({ ...action, horizontal: false })}>Vertical</button>
              <button type="button" class={action.horizontal ? 'is-selected' : ''} aria-pressed={!!action.horizontal} onClick={() => update({ ...action, horizontal: true })}>Horizontal</button>
            </div>
          </div>
        </DirectionalStep>
      )}
      {(action.type === 'scroll' || action.type === 'mouseX' || action.type === 'mouseY' || action.type === 'mouseXY') && (
        <div class="field">
          {!rotation && <>
            <span class="field-label">{action.type === 'scroll' ? 'Scroll Behavior' : 'Behavior'}</span>
            <div class="segmented" role="group" aria-label={action.type === 'scroll' ? 'Scroll Behavior' : 'Behavior'}>
              <button type="button" class={!action.hold ? 'is-selected' : ''} aria-pressed={!action.hold} onClick={() => update({ ...action, hold: undefined })}>Tap</button>
              <button type="button" class={action.hold ? 'is-selected' : ''} aria-pressed={!!action.hold} onClick={() => update({ ...action, hold: true })}>Hold</button>
            </div>
          </>}
          <span class="hint">{timed ? 'Sends one step when this timed action runs.' : rotation ? 'Encoder rotation sends one step per detent.' : action.hold ? action.type === 'scroll' ? 'Repeats with 100ms between steps while held. Release stops new repeats; a step already started finishes.' : 'Repeats every 8ms while held; release to stop.' : action.type === 'scroll' ? 'Sends one step per press.' : 'Sends one move event per press.'}</span>
        </div>
      )}

      {isPointerAction(action) && <div class="field">
        <span class="field-label">Axis</span>
        <div class="segmented" role="group" aria-label="Axis">
          {([['mouseX', 'X'], ['mouseY', 'Y'], ['mouseXY', 'Both']] as const).map(([type, label]) => (
            <button type="button" class={action.type === type ? 'is-selected' : ''} aria-pressed={action.type === type} onClick={() => setMovementAxis(type)}>{label}</button>
          ))}
        </div>
        <span class="hint">{action.type === 'mouseXY' ? 'Mouse counts in steps of 4, actual distance depends on computer settings.' : 'Actual mouse distance depends on computer settings.'}</span>
      </div>}

      {action.type === 'mouseX' && (
        <DirectionalStep directionFirst label="Amount" directionLabel="Direction" negativeLabel="Left" positiveLabel="Right" hint={action.hold ? 'Mouse counts per repeat.' : undefined} value={action.delta} onChange={(delta) => update({ ...action, delta })} />
      )}
      {action.type === 'mouseY' && (
        <DirectionalStep directionFirst label="Amount" directionLabel="Direction" negativeLabel="Up" positiveLabel="Down" hint={action.hold ? 'Mouse counts per repeat.' : undefined} value={action.delta} onChange={(delta) => update({ ...action, delta })} />
      )}

      {action.type === 'mouseXY' && <>
        <DirectionalStep directionFirst label="Horizontal Amount" directionLabel="Horizontal Direction" negativeLabel="Left" positiveLabel="Right" min={4} max={64} step={4} value={action.x} onChange={x => update({ ...action, x })} />
        <DirectionalStep directionFirst label="Vertical Amount" directionLabel="Vertical Direction" negativeLabel="Up" positiveLabel="Down" min={4} max={64} step={4} value={action.y} onChange={y => update({ ...action, y })} />
      </>}

      {(action.type === 'consumer' || action.type === 'consumerHold' || action.type === 'consumerModified' || action.type === 'consumerModifiedHold') && (
        <ConsumerControl key={JSON.stringify(slot) + action.type} action={action} onChange={update} />
      )}

      {action.type === 'string' && (
        <label class="field">
          <span class="field-label">Text <output>{action.text.length + 1} byte{action.text.length === 0 ? '' : 's'}</output></span>
          <textarea rows={4} value={action.text} spellcheck={false} onKeyDown={(e) => {
            if (e.key !== 'Tab' || e.shiftKey || e.altKey || e.ctrlKey || e.metaKey || e.isComposing) return;
            e.preventDefault();
            e.stopPropagation();
            // Native insertion preserves the browser's typing undo/redo history
            // and emits input, which updates the profile through onInput below.
            // Assigning textarea.value here clears that history in browsers.
            document.execCommand('insertText', false, '\t');
          }} onInput={(e) => update({ ...action, text: normalizeText((e.target as HTMLTextAreaElement).value) })} placeholder="Typed with the US keyboard layout" />
          {action.text.length > 0 && <span class="hint" style={{ whiteSpace: 'pre-wrap', overflowWrap: 'anywhere' }}>Preview: “{visibleText(action.text)}”</span>}
          {savedStrings.length > 0 && (
            <select aria-label="Reuse an Existing String" value="" onChange={(e) => {
              const text = (e.target as HTMLSelectElement).value;
              if (text) update({ ...action, text });
            }}>
              <option value="">Reuse an Existing String…</option>
              {savedStrings.map((text) => <option key={text} value={text}>{visibleText(text)}</option>)}
            </select>
          )}
          <span class="hint">Printable ASCII, tab (⇥) and newline (↵) only. Tab inserts a tab; Shift+Tab moves focus out. Identical strings across layers and chords share one copy in device storage. Output depends on the host's keyboard layout.</span>
        </label>
      )}

      {(action.type === 'setLayer' || action.type === 'oneShotSetLayer' || action.type === 'momentaryLayer') && (
        <label class="field">
          <span class="field-label">Target Layer</span>
          <select value={action.layer} onChange={(e) => update({ ...action, layer: Number((e.target as HTMLSelectElement).value) })}>
            {p.layers.map((_, i) => <option key={i} value={i}>{layerName(i)}{slot.kind !== 'timed' && i === slot.layer ? ' (this layer)' : ''}</option>)}
            {action.type !== 'momentaryLayer' && <option value={PREVIOUS_LAYER}>Previous Layer</option>}
            {action.layer >= layerCount && !isPreviousLayer(action) && <option value={action.layer}>Layer {action.layer + 1} (missing)</option>}
          </select>
          {isPreviousLayer(action) && <span class="hint">{action.type === 'oneShotSetLayer'
            ? 'Visit the previous base layer for one action, then return. This does not change layer history.'
            : 'Return to the previous base layer. Repeating this action toggles between the two layers.'} Momentary and one-shot visits do not replace history.</span>}
        </label>
      )}

      {(action.type === 'relativeLayer' || action.type === 'oneShotRelativeLayer' || action.type === 'momentaryRelativeLayer') && (
        <label class="field">
          <span class="field-label">Relative Offset <output>{action.offset > 0 ? `+${action.offset}` : action.offset}</output></span>
          <input type="range" min={1 - maxLayers(p.variant)} max={maxLayers(p.variant) - 1} step={1} value={action.offset} aria-label="Relative Offset" onInput={(e) => update({ ...action, offset: Number((e.target as HTMLInputElement).value) })} />
          <span class="hint">{action.type === 'momentaryRelativeLayer' ? 'Relative to the selected base layer at press time. The target stays fixed until release.' : slot.kind === 'timed' ? 'Relative to the active layer when the timer fires.' : `Layer ${slot.layer + 1} → Layer ${relativeTargetLayer(slot.layer, action.offset, layerCount) + 1}`}</span>
        </label>
      )}

      {slot.kind !== 'timed' && (((action.type === 'setLayer' || action.type === 'oneShotSetLayer' || action.type === 'momentaryLayer') && action.layer === slot.layer) ||
        ((action.type === 'relativeLayer' || action.type === 'oneShotRelativeLayer' || action.type === 'momentaryRelativeLayer') && relativeTargetLayer(slot.layer, action.offset, layerCount) === slot.layer)) && (
        <div class="notice notice-info">Changing to the same layer is useful to display the current layer's indicator</div>
      )}

      {problem && <p class="problem" role="alert">{problem}</p>}

      {keyIndex !== null && (
        <div class="field led-color-field">
          <span class="field-label">LED Color on Key Press</span>
          <div class="color-toolbar">
            <span class="color-selection">
              <span class={`color-selection-dot ${layer.leds[keyIndex] === 15 ? 'swatch-off' : ''}`} style={`--c:${PALETTE[layer.leds[keyIndex]!]?.hex ?? '#000000'}`} aria-hidden="true" />
              {PALETTE[layer.leds[keyIndex]!]?.name ?? 'Unknown'}
            </span>
            {keyCount(p.variant) > 1 && (
              <button type="button" class="btn btn-small color-apply" title="Apply this color to every key on the current layer" onClick={() => updateProfile((d) => { d.layers[slot.layer]!.leds = d.layers[slot.layer]!.leds.map(() => layer.leds[keyIndex]!); })}>
                Apply to Layer
              </button>
            )}
          </div>
          <div class="palette" role="radiogroup" aria-label="LED Color">
            {PALETTE.map((c) => (
              <button
                key={c.index}
                type="button"
                role="radio"
                aria-label={c.name}
                aria-checked={layer.leds[keyIndex] === c.index}
                class={`swatch-btn ${layer.leds[keyIndex] === c.index ? 'is-selected' : ''} ${c.index === 15 ? 'swatch-off' : ''}`}
                style={`--c:${c.hex}`}
                title={c.name}
                onClick={() => updateProfile((d) => { d.layers[slot.layer]!.leds[keyIndex] = c.index; }, `led:${slot.layer}:${keyIndex}`)}
              />
            ))}
          </div>
          <ColorPreview color={layer.leds[keyIndex]!} />
        </div>
      )}
      {showScrollTest && <ScrollTest onClose={() => setShowScrollTest(false)} />}
    </section>
  );
}
